// GENERATED by packages/schema/generate.mjs from packages/schema/schema/*.schema.json. Do not edit:
// change a schema and run `npm run schema:generate`; `npm run check:schema` fails while this file is stale, and
// fails when a schema field is neither a UPROPERTY named as its key nor copied here.
//
// BpSchema.h names a field as its JSON key wherever C++ allows, so FJsonObjectConverter fills it. The rest are
// `<Key>_` fields the converter skips (it matches property names to keys, case-insensitively); FixUp copies the
// raw key into each one after the converter ran:
//   a key that is no C++ name (short, default, $schema)   JsonValueToUProperty into the renamed UPROPERTY
//   a value no UPROPERTY type holds (glyph, cross_refs)    its condensed JSON text into an FString
// Read every document with BpSchema::FromJson, never with JsonObjectToUStruct alone.
#pragma once

#include "CoreMinimal.h"
#include "Dom/JsonObject.h"
#include "JsonObjectConverter.h"
#include "Policies/CondensedJsonPrintPolicy.h"
#include "Serialization/JsonSerializer.h"
#include "Serialization/JsonWriter.h"
#include "BpSchema.h"

namespace BpSchema
{
	inline bool FixUp(const FJsonObject& Json, FBpAppStructure& Out);
	inline bool FixUp(const FJsonObject& Json, FBpContext& Out);
	inline bool FixUp(const FJsonObject& Json, FBpLensEntry& Out);
	inline bool FixUp(const FJsonObject& Json, FBpLensManifest& Out);
	inline bool FixUp(const FJsonObject& Json, FBpHealth& Out);
	inline bool FixUp(const FJsonObject& Json, FBpRule& Out);
	inline bool FixUp(const FJsonObject& Json, FBpPresentation& Out);
	inline bool FixUp(const FJsonObject& Json, FBpAppStructureEvent& Out);

	/** Json[Key] into the UPROPERTY Field of Out, as the converter would have read it. A missing key keeps the default. */
	template <typename T>
	bool CopyKey(const FJsonObject& Json, const TCHAR* Key, const FName Field, T& Out)
	{
		const TSharedPtr<FJsonValue> Value = Json.TryGetField(Key);
		if (!Value.IsValid()) return true;
		FProperty* Property = T::StaticStruct()->FindPropertyByName(Field);
		return Property && FJsonObjectConverter::JsonValueToUProperty(Value, Property, Property->ContainerPtrToValuePtr<void>(&Out), 0, 0);
	}

	/** Json[Key] as condensed JSON text into Out (a bare string keeps its quotes). A missing key leaves Out empty. */
	inline bool CopyRaw(const FJsonObject& Json, const TCHAR* Key, FString& Out)
	{
		const TSharedPtr<FJsonValue> Value = Json.TryGetField(Key);
		if (!Value.IsValid()) return true;
		Out.Reset();
		const TSharedRef<TJsonWriter<TCHAR, TCondensedJsonPrintPolicy<TCHAR>>> Writer = TJsonWriterFactory<TCHAR, TCondensedJsonPrintPolicy<TCHAR>>::Create(&Out);
		return FJsonSerializer::Serialize(Value, FString(), Writer);
	}

	/** FixUp on the struct held at Json[Key]. */
	template <typename T>
	bool FixUpOne(const FJsonObject& Json, const TCHAR* Key, T& Out)
	{
		const TSharedPtr<FJsonObject>* Object = nullptr;
		return !Json.TryGetObjectField(Key, Object) || FixUp(**Object, Out);
	}

	/** FixUp on each struct of the array at Json[Key]; the converter filled Out in the same order. */
	template <typename T>
	bool FixUpArray(const FJsonObject& Json, const TCHAR* Key, TArray<T>& Out)
	{
		const TArray<TSharedPtr<FJsonValue>>* Items = nullptr;
		if (!Json.TryGetArrayField(Key, Items)) return true;
		if (Items->Num() != Out.Num()) return false;
		for (int32 I = 0; I < Items->Num(); ++I)
		{
			const TSharedPtr<FJsonObject>* Object = nullptr;
			if (!(*Items)[I]->TryGetObject(Object) || !FixUp(**Object, Out[I])) return false;
		}
		return true;
	}

	/** FixUp on each struct of the object at Json[Key], by key. */
	template <typename T>
	bool FixUpMap(const FJsonObject& Json, const TCHAR* Key, TMap<FString, T>& Out)
	{
		const TSharedPtr<FJsonObject>* Object = nullptr;
		if (!Json.TryGetObjectField(Key, Object)) return true;
		for (TPair<FString, T>& Entry : Out)
		{
			const TSharedPtr<FJsonObject>* Value = nullptr;
			if (!(*Object)->TryGetObjectField(Entry.Key, Value) || !FixUp(**Value, Entry.Value)) return false;
		}
		return true;
	}

	inline bool FixUp(const FJsonObject& Json, FBpAppStructure& Out)
	{
		bool bOk = true;
		bOk &= CopyKey(Json, TEXT("$schema"), GET_MEMBER_NAME_CHECKED(FBpAppStructure, Schema_), Out);
		bOk &= FixUpArray(Json, TEXT("contexts"), Out.contexts);
		bOk &= FixUpArray(Json, TEXT("lenses"), Out.lenses);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpContext& Out)
	{
		bool bOk = true;
		bOk &= CopyRaw(Json, TEXT("cross_refs"), Out.CrossRefs_);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpLensEntry& Out)
	{
		bool bOk = true;
		bOk &= FixUpOne(Json, TEXT("manifest"), Out.manifest);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpLensManifest& Out)
	{
		bool bOk = true;
		bOk &= CopyKey(Json, TEXT("$schema"), GET_MEMBER_NAME_CHECKED(FBpLensManifest, Schema_), Out);
		bOk &= CopyKey(Json, TEXT("short"), GET_MEMBER_NAME_CHECKED(FBpLensManifest, Short_), Out);
		bOk &= FixUpOne(Json, TEXT("health"), Out.health);
		bOk &= FixUpOne(Json, TEXT("presentation"), Out.presentation);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpHealth& Out)
	{
		bool bOk = true;
		bOk &= FixUpArray(Json, TEXT("rules"), Out.rules);
		bOk &= CopyKey(Json, TEXT("default"), GET_MEMBER_NAME_CHECKED(FBpHealth, Default_), Out);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpRule& Out)
	{
		bool bOk = true;
		bOk &= CopyKey(Json, TEXT("short"), GET_MEMBER_NAME_CHECKED(FBpRule, Short_), Out);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpPresentation& Out)
	{
		bool bOk = true;
		bOk &= CopyRaw(Json, TEXT("glyph"), Out.Glyph_);
		return bOk;
	}

	inline bool FixUp(const FJsonObject& Json, FBpAppStructureEvent& Out)
	{
		(void)Json; (void)Out;
		return true; // nothing carried
	}

	/** The one way BpLink reads a document: FJsonObjectConverter for the mapped fields, then FixUp for the carried ones. */
	template <typename T>
	bool FromJson(const TSharedRef<FJsonObject>& Json, T& Out)
	{
		return FJsonObjectConverter::JsonObjectToUStruct(Json, &Out, 0, 0) && FixUp(*Json, Out);
	}
}
